\begin{figure}[t]
    \centering
    \includegraphics[width=\textwidth]{figures_and_tables/fig1_icp_overview_target.pdf}
    \caption{\textbf{Intelligence Control Plane (ICP) overview.} \textbf{Left:} an Intelligence System binds a model, a middleware stack, and a machine; highlighted boxes trace one composed system. \textbf{Middle:} a local model on a laptop escalating through owned accelerators to a frontier provider comes within \CompAccGap\ points of the Claude Fable~5.1 anchor at \CompMult\ lower cost per task, a point no individual model occupies (overlapping markers are offset slightly). \textbf{Right:} the three-stage system completes \PanelCAcc\ of TerminalBench~V2.1 at \$\PanelCUSD\ per task, with \LFLOCALSHARE\ of tasks finishing on the laptop and \PanelCNoClosed\ never reaching a closed-source provider.}
    \label{fig:stack}
\end{figure}

\begin{figure}[t]
    \centering
    \includegraphics[width=0.95\textwidth]{figures_and_tables/fig1_ai_stack.png}
    \caption{\textbf{The three axes of the Intelligence Control Plane, and the coordinates this paper scores within each.} Dashed entries mark what each axis admits beyond what we enumerate. Appendix~\ref{app:tiers} lists the model tiers, and Tables~\ref{tab:middleware} and~\ref{tab:machines} the middleware and machines we score.}
    \label{fig:axes}
\end{figure}

\begin{figure}[t]
    \centering
    \includegraphics[width=\textwidth]{figures_and_tables/fig3_policy_families_target.pdf}
    \caption{\textbf{The four orchestration policies differ in what $\pi$ is allowed to read, and when.} Panels are policy families over configurations $c=(m,w,h)$ of model, middleware, and machine. Query routing reads the prompt $t$ before anything runs; local-first escalation reads the cheapest configuration's trace $\tau_1$ and escalates only on a failure. Routing reads a prediction and escalation what happened, the distinction \S\ref{sec:signal} shows matters.}
    \label{fig:policies}
\end{figure}

\begin{figure}[t]
    \centering
    \includegraphics[width=0.95\textwidth]{figures_and_tables/fig2_ipd_ipj_target.pdf}
    \caption{\textbf{Fixed systems spread far more in cost than in accuracy.} Accuracy against dollars per task (left, Claude Fable~5.1 included) and joules per task (right, open-weight tiers only, since closed-weight providers report no per-task energy). Color is the company; marker area is total parameters (open-weight) or output price (closed-weight), and the number of sides is its rank within the company. Self-served tiers pair leaderboard-protocol accuracy with the cost and energy of their serving configuration (Appendix~\ref{app:measure}). Tiers below 60\% are omitted, and Claude Opus~4.8, GPT-5.5, and Qwen3.6-27B removed for legibility (Appendix~\ref{app:excluded}).}
    \label{fig:ipd-ipj}
\end{figure}

\begin{figure}[t]
    \centering
    \includegraphics[width=0.95\textwidth]{figures_and_tables/fig_task_flow.pdf}
    \caption{\textbf{Intelligence System composition on TerminalBench~V2.1: \LFLOCALSHARE\ of tasks stay local.} Band widths are shares of all tasks; hatched bands are escalated work, paid for and discarded.}
    \label{fig:taskflow}
\end{figure}

\begin{figure}[t]
    \centering
    \includegraphics[width=0.8\textwidth]{figures_and_tables/fig7_apple_silicon.pdf}
    \caption{\textbf{Holding the model fixed, two generations of consumer silicon cut energy per query 2.2$\times$ to 3.4$\times$.} Seven open-weight models at Q4\_K\_M on the \textsc{ipw} benchmark, on Mac Studio M3~Ultra, Mac Studio M4~Max, and MacBook Pro M5~Max \citep{applem4,macstudio2025,applem5}; the ordering is monotone for every model, with a mean ratio of 2.7$\times$. Energy only: per-platform accuracy varies by up to 15.9 points for an identical model and quantization at $N$ of 15 to 30, inside binomial noise. Joules per query are not comparable to joules per task on TerminalBench V2.1 (\S\ref{sec:measure}).}
    \label{fig:apple}
\end{figure}

\begin{figure}[t]
    \centering
    \includegraphics[width=0.8\textwidth]{figures_and_tables/fig5_cascade_frontier.pdf}
    \caption{\textbf{In the earlier single-run grid, four of the ten escalate-on-failure plans over the GLM-5.2 first stage lie on the Pareto frontier.} The four GLM-5.2 cells of the grid behind Table~\ref{tab:grid} that no other cell matches or beats on both accuracy and cost, with GLM-5.2 alone, on the marginal basis (Appendix~\ref{app:cost}); the cheapest, GLM-5.2 $\rightarrow$ DeepSeek-V4-Flash at 74.2\% and \$0.0231 per task, ranks below the table's top ten. The other six GLM-5.2 cells are not plotted: GLM-5.2 $\rightarrow$ GPT-5.6-sol is cheaper than each of them and more accurate than all but GLM-5.2 $\rightarrow$ Gemini~3.7~Flash, which it ties at 84.3\%.}
    \label{fig:cascade}
\end{figure}

\begin{figure}[t]
    \centering
    \includegraphics[width=0.8\textwidth]{figures_and_tables/fig2_ipj_longitudinal.png}
    \caption{\textbf{Local intelligence per joule has improved 34.6$\times$ since 2024.} Accuracy per joule for the state-of-the-art local model and accelerator pairing at each release date, split into machine and model gains, whose compounding makes a laptop-class local tier competent enough to compose with a frontier one. The series and its split are from the published Intelligence per Watt results \citep{ipw2025}; accuracy there is a mean over MMLU-Pro, SuperGPQA, NaturalReasoning, and WildChat, not TerminalBench~V2.1. Every result we measure ourselves is cross-sectional.}
    \label{fig:longitudinal}
\end{figure}

\begin{table}[t]
\centering
\caption{\textbf{Of the five middleware categories, we vary the orchestration strategy and hold the other four fixed.} Holding the engine at vLLM moves energy per token by \ENGGAPPCT\%, against the \JSPANMEASURED$\times$ in energy per task separating the tiers we measure; Appendix~\ref{app:beyond} gives what one serving flag costs an on-prem tier.}
\label{tab:middleware}
\setlength{\tabcolsep}{4pt}
\begin{tabularx}{\textwidth}{@{}l >{\raggedright\arraybackslash}X >{\raggedright\arraybackslash}p{0.27\textwidth}@{}}
